# Generated by `cargo xtask formula` in https://github.com/michel-onstein/acs for each release
# (scripts/update-tap.sh): edit the generator there, not this file.
# acs-version: 0.22.0
#
# acs releases are signed; SHA256SUMS.sig is checked against this key:
#   ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAILbxQW5C9X7CdwcQ4bab0gsQi4Evk2xfgmI/972dlHCb acs release signing
# Verify a release by hand:
#   printf 'releases@acs namespaces="acs-release" %s\n' "$key" > allowed
#   ssh-keygen -Y verify -f allowed -I releases@acs -n acs-release -s SHA256SUMS.sig < SHA256SUMS
class Acs < Formula
  desc "Persistent, reconnecting remote shells over ssh"
  homepage "https://github.com/michel-onstein/acs"
  license "MIT"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/michel-onstein/acs/releases/download/0.22.0/acs-0.22.0-aarch64-apple-darwin.tar.gz"
      sha256 "2f48d50908b13a61bf0e90a37bfdcf04ea2e4f3bf7089d9a97930ff9d86e2267"
    end

    on_intel do
      url "https://github.com/michel-onstein/acs/releases/download/0.22.0/acs-0.22.0-x86_64-apple-darwin.tar.gz"
      sha256 "36e61163d7df81834f4c210134017b73c1879a332a7123ab38565c630569c8bd"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/michel-onstein/acs/releases/download/0.22.0/acs-0.22.0-aarch64-unknown-linux-musl.tar.gz"
      sha256 "d8df935157f104a90058609ffd63fac10c4d41180edaa57297f798d02618350b"
    end

    on_intel do
      url "https://github.com/michel-onstein/acs/releases/download/0.22.0/acs-0.22.0-x86_64-unknown-linux-musl.tar.gz"
      sha256 "6a7adbcaaab3e849e431d6f1d247a957967711969b2b661d225a8e9196ffb753"
    end
  end

  def install
    bin.install "acs"
    bin.install_symlink "acs" => "acscp"
  end

  test do
    out = shell_output("#{bin}/acs --version")
    assert_match "acs #{version} ", out
    remotes = out[/^installs remotes: (.*)$/, 1].to_s.split(", ")
    assert_includes remotes, "x86_64-unknown-linux-musl"
    assert_includes remotes, "aarch64-unknown-linux-musl"
    assert_match "acs #{version} ", shell_output("#{bin}/acscp --version")
  end
end
